window.DECKS.push({"slug":"obgyn2","name":"Obgyn 2","folder":"OBGYN 2","questions":[
{"id":"og2-01","p":6,"stem":"Wanita 23 tahun G1P0A0 hamil 23 minggu kejang 1× di rumah. Somnolen, TD 200/105. Tatalaksana yang tepat adalah…","opts":["Stabilisasi + nifedipin oral","Stabilisasi + MgSO₄","Stabilisasi + persiapan terminasi","Stabilisasi + propranolol","Stabilisasi + observasi kehamilan"],"ans":2,"why":"Kejang pada preeklampsia adalah EKLAMPSIA. Kunci dosen: stabilisasi (ABC, MgSO₄ sebagai antikonvulsan, antihipertensi) lalu TERMINASI kehamilan, karena satu-satunya terapi definitif adalah melahirkan janin dan plasenta, berapa pun usia kehamilannya.","ref":[5],"tags":["Eklampsia"],"skdi":"3B","src":"coretan","cards":[{"q":"Terapi definitif eklampsia?","a":"Terminasi kehamilan"},{"q":"Antikonvulsan pilihan eklampsia?","a":"MgSO₄"}]},
{"id":"og2-02","p":6,"stem":"Wanita 38 tahun G1P0A0 hamil 24 minggu ANC tanpa keluhan; riwayat hipertensi sejak sebelum hamil. TD 165/80, proteinuria +++. Diagnosisnya adalah…","opts":["Hipertensi kronis","Hipertensi gestasional","Preeklampsia","Superimposed preeklampsia","Eklampsia"],"ans":3,"why":"Hipertensi yang SUDAH ada sebelum hamil (atau < 20 minggu), lalu muncul proteinuria setelah 20 minggu, adalah hipertensi kronis dengan superimposed preeklampsia.","ref":[5],"tags":["Hipertensi kehamilan"],"skdi":"3B","src":"coretan","cards":[{"q":"Hipertensi kronis dalam kehamilan?","a":"HT sebelum hamil / < 20 minggu"},{"q":"Hipertensi gestasional?","a":"HT ≥ 20 minggu tanpa proteinuria"},{"q":"Superimposed preeklampsia?","a":"HT kronis + proteinuria baru ≥ 20 minggu"}]},
{"id":"og2-03","p":6,"stem":"Wanita 21 tahun G1P1A0 hamil 36 minggu ke IGD dengan pusing, tanpa mual muntah. TD 150/100, proteinuria +. Pilihan antihipertensi yang tepat adalah…","opts":["Kaptopril","Candesartan","Nifedipin","Klortiazid","Metildopa"],"ans":4,"why":"Preeklampsia (TD ≥ 140/90 + proteinuria ≥ 20 minggu) dengan TD < 160/110 (belum berat): antihipertensi oral yang aman pada kehamilan adalah metildopa (kunci dosen). Nifedipin dan labetalol juga dipakai, terutama untuk krisis. ACEI/ARB (kaptopril, candesartan) kontraindikasi karena teratogenik.","ref":[5],"tags":["Preeklampsia","Antihipertensi"],"skdi":"3B","src":"coretan","cards":[{"q":"Antihipertensi oral aman untuk ibu hamil?","a":"Metildopa, nifedipin, labetalol"},{"q":"Antihipertensi kontraindikasi pada kehamilan?","a":"ACEI & ARB"}]},
{"id":"og2-04","p":6,"stem":"Wanita 20 tahun G1P0A0 hamil 22 minggu ANC tanpa keluhan. TD 140/90. Tatalaksana yang tepat untuk mencegah komplikasi adalah…","opts":["Amlodipin","MgSO₄","Nifedipin","Kaptopril","Propranolol"],"ans":2,"why":"Hipertensi gestasional (≥ 20 minggu tanpa proteinuria). Kunci dosen: kontrol TD dengan antihipertensi yang aman (nifedipin) untuk mencegah progresi ke preeklampsia atau eklampsia. MgSO₄ hanya untuk preeklampsia berat atau eklampsia.","ref":[5],"tags":["Hipertensi gestasional"],"skdi":"3B","src":"coretan","cards":[]},
{"id":"og2-05","p":10,"stem":"Wanita 30 tahun G2P1A0 hamil 15 minggu muntah sejak 1 hari (±6×/hari), mual mencium bau masakan, tidak bisa makan dan minum. TD 90/60, N 105, mata cowong. Diagnosis yang tepat adalah…","opts":["Emesis gravidarum","Hiperemesis gravidarum grade 1","Hiperemesis gravidarum grade 2","Hiperemesis gravidarum grade 3","Hiperemesis gravidarum grade 4"],"ans":1,"why":"Muntah berlebihan yang mengganggu asupan dengan tanda dehidrasi (takikardia, hipotensi, mata cekung), tetapi kesadaran baik, adalah hiperemesis gravidarum tingkat I. Tingkat II: apatis, ikterus, oliguria, aseton. Tingkat III: penurunan kesadaran, ensefalopati Wernicke.","ref":[7],"tags":["Hiperemesis gravidarum"],"skdi":"3B","src":"coretan","cards":[{"q":"Hiperemesis grade I: tanda kunci?","a":"Dehidrasi, nadi ↑, sadar baik"},{"q":"Hiperemesis grade III: tanda kunci?","a":"Penurunan kesadaran (Wernicke)"}]},
{"id":"og2-06","p":10,"stem":"Wanita 30 tahun G2P1A0 hamil 16 minggu ANC, tanpa keluhan; riwayat anemia pada kehamilan pertama. Hb 8 g/dL. Tatalaksana yang tepat adalah…","opts":["Sulfas ferosus 30 mg","Sulfas ferosus 60 mg","Sulfas ferosus 90 mg","Sulfas ferosus 180 mg","Sulfas ferosus 240 mg"],"ans":3,"why":"Anemia defisiensi besi pada kehamilan (Hb < 11; Hb 7–10 sedang) diterapi besi elemental terapeutik 120–200 mg/hari (catatan dosen), di sini 180 mg. Dosis profilaksis hanya 60 mg/hari.","ref":[8],"tags":["Anemia kehamilan"],"skdi":"4A","src":"coretan","cards":[{"q":"Batas anemia pada ibu hamil?","a":"Hb < 11 g/dL"},{"q":"Besi profilaksis ibu hamil?","a":"60 mg elemental/hari"},{"q":"Besi terapeutik anemia defisiensi besi kehamilan?","a":"120–200 mg elemental/hari"}]},
{"id":"og2-07","p":10,"stem":"Wanita 20 tahun G1P0A0 hamil 10 minggu sering pusing, berkunang-kunang, hampir pingsan. Hb 7,2, MCV 75. Tatalaksana yang tepat adalah…","opts":["Besi elemental 180 mg","Transfusi PRC","Vitamin B12 1×250–1000 mcg","Asam folat 1×2 mg","Rujuk ke penyakit dalam"],"ans":1,"why":"Kunci dosen: anemia berat dan SIMTOMATIK (pusing, hampir pingsan) dengan Hb ±7 → transfusi PRC. Besi oral butuh waktu, sedangkan pasien sudah bergejala.","ref":[8],"tags":["Anemia kehamilan"],"skdi":"4A","src":"coretan","cards":[]},
{"id":"og2-08","p":10,"stem":"Wanita 19 tahun G1P0A0 hamil 15 minggu ANC. Hb 7,8 g/dL. Tatalaksana yang tepat adalah…","opts":["Sulfas ferosus 30 mg","Sulfas ferosus 60 mg","Sulfas ferosus 90 mg","Sulfas ferosus 180 mg","Sulfas ferosus 240 mg"],"ans":3,"why":"Anemia sedang tanpa gejala pada kehamilan diterapi besi oral dosis terapeutik (120–200 mg elemental/hari), yaitu 180 mg.","ref":[8],"tags":["Anemia kehamilan"],"skdi":"4A","src":"coretan","cards":[]},
{"id":"og2-09","p":18,"stem":"Wanita 24 tahun G1P0A0 hamil 25 minggu keluar cairan dari jalan lahir, tanpa kencang-kencang, cairan tidak berbau, tanpa demam. Pemeriksaan penunjang yang tepat adalah…","opts":["Darah lengkap","Tes nitrazin","Urin rutin","Tes Tzanck","USG"],"ans":1,"why":"Konfirmasi ketuban pecah dengan tes nitrazin (kertas lakmus menjadi biru karena pH cairan ketuban basa 7–7,5), atau tes fern (pakis). KPD preterm (< 37 minggu) tanpa infeksi diterapi konservatif (ekspektatif).","ref":[12],"tags":["KPD"],"skdi":"3A","src":"coretan","cards":[{"q":"Tes nitrazin positif pada KPD?","a":"Kertas lakmus jadi biru (pH basa)"}]},
{"id":"og2-10","p":18,"stem":"Wanita 23 tahun P1A0, 1 bulan pasca-SC, demam 3 hari dan cairan berbau dari vagina. Fundus uteri setinggi simfisis dengan nyeri tekan. Tatalaksana yang tepat adalah…","opts":["Histerektomi","Kuretase","Manual plasenta","Klindamisin 900 mg/8 jam IV + gentamisin 5 mg/kgBB/24 jam IV","Ampisilin 2 g/6 jam IV + gentamisin 5 mg/kgBB/24 jam IV"],"ans":3,"why":"Endometritis postpartum (demam, lokia berbau, uterus nyeri tekan), terutama setelah SC, diterapi klindamisin + gentamisin IV sampai bebas demam 24–48 jam.","ref":[14],"tags":["Endometritis"],"skdi":"3B","src":"coretan","cards":[{"q":"Antibiotik endometritis postpartum?","a":"Klindamisin + gentamisin IV"}]},
{"id":"og2-11","p":18,"stem":"Wanita 26 tahun G1P0A0 hamil 31 minggu keluar cairan dari jalan lahir 5 jam, disertai demam, tanpa kencang-kencang. DJJ 144, VT tidak ada pembukaan. Tatalaksana AWAL yang tepat adalah…","opts":["Rawat inap + ampisilin IV","Rawat inap + deksametason IV","Rawat inap + paracetamol IV","Rawat jalan + amoksisilin oral","Rawat jalan + prednison oral"],"ans":1,"why":"Kunci dosen: KPD preterm (< 34 minggu), rawat inap dan kortikosteroid (deksametason 6 mg IM/IV tiap 12 jam, 4 dosis) untuk pematangan paru janin. Catatan: dengan DEMAM, curigai korioamnionitis, sehingga antibiotik spektrum luas juga wajib dan kehamilan diterminasi bila infeksi terbukti.","ref":[12,13],"tags":["KPD preterm","Korioamnionitis"],"skdi":"3A","src":"coretan","cards":[{"q":"Kortikosteroid pematangan paru janin?","a":"Deksametason 6 mg tiap 12 jam × 4 dosis"},{"q":"Batas usia kehamilan pemberian kortikosteroid antenatal?","a":"24–34 minggu"}]},
{"id":"og2-12","p":18,"stem":"Wanita 22 tahun G2P0A1 hamil 30 minggu tidak merasakan gerak janin 2 hari, tanpa nyeri perut atau perdarahan. USG seperti pada gambar (tanpa aktivitas jantung, Spalding sign). Diagnosisnya adalah…","opts":["Abortus","Solusio plasenta","IUFD","IUGR","Gawat janin"],"ans":2,"why":"Janin mati dalam kandungan setelah 20 minggu (tanpa gerak janin dan DJJ; USG tanpa denyut jantung, tulang kepala tumpang tindih/Spalding sign) adalah IUFD. Kematian < 20 minggu disebut abortus.","ref":[15],"tags":["IUFD"],"skdi":"3A","src":"coretan","img":true,"cards":[{"q":"IUFD = kematian janin usia…?","a":"≥ 20 minggu (< 20 minggu = abortus)"},{"q":"Spalding sign?","a":"Tulang kepala janin tumpang tindih (IUFD)"}]},
{"id":"og2-13","p":23,"stem":"Perempuan 32 tahun G2P1A0 hamil 34 minggu dengan riwayat SC, diabetes gestasional, superimposed preeklampsia, PCOS, dan plasenta previa marginal. Faktor risiko makrosomia janin pada kasus ini adalah…","opts":["Superimposed preeklampsia","Plasenta previa marginal","Diabetes gestasional","PCOS","Riwayat SC"],"ans":2,"why":"Hiperglikemia ibu menyebabkan hiperinsulinemia janin (hormon pertumbuhan anabolik), sehingga terjadi makrosomia (> 4000 g). Preeklampsia justru menyebabkan IUGR.","ref":[20],"tags":["Makrosomia"],"skdi":"3A","src":"coretan","cards":[{"q":"Makrosomia = berat lahir…?","a":"> 4000 g"},{"q":"Faktor risiko utama makrosomia?","a":"Diabetes ibu"}]},
{"id":"og2-14","p":23,"stem":"Wanita 34 tahun G2P1A0 hamil 16 minggu dengan bengkak kedua kaki. TFU 40 cm, LP 100 cm, palpasi sulit, DJJ sulit ditemukan. Diagnosis yang tepat adalah…","opts":["Gemelli","Polihidramnion","Oligohidramnion","DM gestasional","Makrosomia"],"ans":1,"why":"Uterus jauh lebih besar dari usia kehamilan dengan dinding tegang, bagian janin sulit diraba, dan DJJ sulit didengar adalah polihidramnion (cairan ketuban > 2000 mL; AFI > 24/25 cm). Konfirmasi dengan USG.","ref":[19,21],"tags":["Polihidramnion"],"skdi":"3A","src":"coretan","cards":[{"q":"Polihidramnion: nilai AFI?","a":"> 24–25 cm (> 2 L)"},{"q":"Oligohidramnion: nilai AFI?","a":"< 5 cm"}]},
{"id":"og2-15","p":23,"stem":"Perempuan 24 tahun G2P1A0 hamil 31 minggu; USG menunjukkan lambda sign. Diagnosisnya adalah…","opts":["Gemelli monokorion monoamnion","Gemelli monokorion diamnion","Gemelli dikorion monoamnion","Gemelli dikorion diamnion","Janin tunggal hidup"],"ans":3,"why":"Lambda (twin peak) sign, yaitu jaringan korion yang menjorok di antara membran, menunjukkan gemelli DIKORION diamnion. T sign (membran tipis tegak lurus) menunjukkan MONOKORION diamnion.","ref":[22],"tags":["Gemelli"],"skdi":"3A","src":"coretan","cards":[{"q":"Lambda sign pada USG gemelli?","a":"Dikorion diamnion"},{"q":"T sign pada USG gemelli?","a":"Monokorion diamnion"}]},
{"id":"og2-16","p":23,"stem":"Perempuan 29 tahun G2P1A0 hamil 30 minggu; USG menunjukkan T sign. Diagnosisnya adalah…","opts":["Gemelli monokorion monoamnion","Gemelli monokorion diamnion","Gemelli dikorion monoamnion","Gemelli dikorion diamnion","Janin tunggal hidup"],"ans":1,"why":"T sign (membran pemisah tipis yang bertemu plasenta tunggal dengan sudut tegak lurus) adalah gemelli monokorion diamnion, yang berisiko twin-to-twin transfusion syndrome.","ref":[22],"tags":["Gemelli"],"skdi":"3A","src":"coretan","cards":[]},
{"id":"og2-17","p":31,"stem":"Wanita 57 tahun berdarah setelah berhubungan seksual, nyeri, dan bau busuk dari kemaluan. Massa 2×2 cm di serviks, berbenjol-benjol. Gold standard pemeriksaan penunjang adalah…","opts":["USG abdomen","USG transvaginal","Pap smear","Biopsi","IVA test"],"ans":3,"why":"Massa serviks yang mencurigakan Ca serviks (perdarahan pascasanggama, keputihan berbau) memerlukan diagnosis pasti dengan biopsi histopatologi. Pap smear dan IVA adalah alat SKRINING.","ref":[27,28],"tags":["Ca serviks"],"skdi":"2","src":"coretan","cards":[{"q":"Gold standard diagnosis Ca serviks?","a":"Biopsi (histopatologi)"},{"q":"Gejala khas Ca serviks?","a":"Perdarahan pascasanggama"}]},
{"id":"og2-18","p":31,"stem":"Wanita 55 tahun datang untuk pap smear, tanpa perdarahan atau dispareunia. Inspekulo: lesi multipel putih kekuningan di permukaan serviks. IVA acetowhite (–). Diagnosisnya adalah…","opts":["Ca serviks","Bartolinitis","Polip serviks","Kista Gartner","Kista Nabothi"],"ans":4,"why":"Benjolan kecil putih-kekuningan multipel di permukaan serviks (kelenjar endoserviks yang tersumbat) adalah kista Nabothi, jinak dan IVA negatif. Kista Gartner berada di dinding lateral vagina (sisa duktus Wolffii).","ref":[26,28],"tags":["Massa serviks"],"skdi":"2","src":"coretan","cards":[{"q":"Kista Nabothi?","a":"Kista putih-kuning kecil di serviks, jinak"},{"q":"Kista Gartner: lokasi?","a":"Dinding lateral vagina"}]},
{"id":"og2-19","p":31,"stem":"Wanita 76 tahun P7A0 benjolan keluar dari kemaluan sejak 2 minggu (prolaps), tanpa keluhan lain; aktivitas sehari-hari dibantu anaknya. Dokter memutuskan memasang cincin pesarium. Kontraindikasi tindakan nonfarmakologis ini adalah…","opts":["Jaringan parut","Postpartum","Kehamilan","Pascamenopause","Demensia"],"ans":4,"why":"Pesarium memerlukan perawatan, pelepasan dan pembersihan, serta kontrol rutin. Kontraindikasinya infeksi pelvis aktif dan pasien yang tidak dapat merawat atau kontrol (demensia, tidak kooperatif). Pascamenopause adalah pengguna terbanyak, bukan kontraindikasi.","ref":[25],"tags":["Prolaps uteri"],"skdi":"3A","src":"coretan","cards":[{"q":"Kontraindikasi pesarium?","a":"Infeksi aktif, pasien tidak bisa merawat/kontrol (demensia)"}]},
{"id":"og2-20","p":31,"stem":"Wanita 23 tahun benjolan di bibir kemaluan 3 hari, nyeri dan tidak nyaman saat berjalan. Massa vulva hiperemis dan nyeri tekan. Tatalaksana yang tepat adalah…","opts":["Trimetoprim-sulfametoksazol","Klindamisin","Sefiksim","Kloramfenikol","Sefadroksil"],"ans":0,"why":"Bartolinitis atau abses Bartholin (benjolan nyeri di labium posterior). Kunci dosen: antibiotik kotrimoksazol (trimetoprim-sulfametoksazol), ditambah insisi dan drainase atau marsupialisasi bila abses.","ref":[26],"tags":["Bartolinitis"],"skdi":"3A","src":"coretan","cards":[{"q":"Tindakan abses Bartholin berulang?","a":"Marsupialisasi"}]},
{"id":"og2-21","p":40,"stem":"Perempuan 46 tahun nyeri haid dan darah haid sangat banyak 5 tahun, perut makin membesar. USG: massa dicurigai leiomioma. Gambaran histopatologi yang sesuai adalah…","opts":["Owl eyes","Starry sky","Whorl-like pattern","Perkijuan","Target sign"],"ans":2,"why":"Leiomioma (mioma uteri) secara histologi berupa berkas otot polos yang tersusun berpusar (whorled pattern). Owl eye: Reed-Sternberg/CMV. Starry sky: limfoma Burkitt. Perkijuan: TB.","ref":[33,34],"tags":["Mioma uteri"],"skdi":"2","src":"slide","cards":[{"q":"Histopatologi mioma uteri?","a":"Whorl-like pattern"}]},
{"id":"og2-22","p":40,"stem":"Anak perempuan 16 tahun belum pernah menstruasi, nyeri perut setiap bulan. Hymen menonjol kebiruan dan tampak obstruksi menonjol di vagina. Diagnosisnya adalah…","opts":["Amenorea","Hematometra","Hematokolpos","Hematosalping","Hipospadia"],"ans":2,"why":"Himen imperforata: darah menstruasi tertampung di VAGINA (hematokolpos) sehingga himen menonjol kebiruan, disertai nyeri siklik dan amenore primer. Bila meluas ke uterus disebut hematometra, ke tuba hematosalping. Terapinya himenotomi.","ref":[37,38],"tags":["Himen imperforata"],"skdi":"2","src":"slide","cards":[{"q":"Darah haid tertampung di vagina disebut…?","a":"Hematokolpos"},{"q":"Terapi himen imperforata?","a":"Himenotomi"}]},
{"id":"og2-23","p":40,"stem":"Wanita 23 tahun nyeri saat menstruasi beberapa bulan, makin berat. USG: ground-glass opacity (kista berisi cairan homogen). Diagnosis yang tepat adalah…","opts":["Endometriosis","Endometrioma","Ca serviks","Mioma uteri","PCOS"],"ans":1,"why":"Dismenore progresif dengan kista ovarium berisi cairan homogen ground-glass (low-level echo) pada USG adalah endometrioma (kista cokelat/kista endometriosis ovarium).","ref":[33,34],"tags":["Endometriosis"],"skdi":"2","src":"slide","cards":[{"q":"USG endometrioma?","a":"Kista ground-glass (cokelat)"}]},
{"id":"og2-24","p":40,"stem":"Wanita 23 tahun haid tidak teratur bertahun-tahun: jarang menstruasi dan darahnya sedikit, tanpa nyeri. Diagnosisnya adalah…","opts":["Amenorea","Oligomenorea","Menometroragia","Metroragia","Menoragia"],"ans":1,"why":"Siklus haid yang jarang (> 35 hari) adalah oligomenore. Amenore: tidak haid ≥ 3 bulan (sekunder). Menoragia: haid banyak atau lama. Metroragia: perdarahan di luar siklus.","ref":[35,36],"tags":["Gangguan haid"],"skdi":"4A","src":"slide","cards":[{"q":"Oligomenore = siklus…?","a":"> 35 hari"},{"q":"Polimenore = siklus…?","a":"< 21 hari"},{"q":"Metroragia?","a":"Perdarahan di luar siklus haid"}]},
{"id":"og2-25","p":46,"stem":"Pasangan suami-istri sulit memiliki anak; rutin berhubungan 3 bulan. Analisis sperma: volume 1,9 mL, motilitas 37%, jumlah 14 juta per ejakulat, morfologi normal 13%. Hasil analisis sperma tersebut adalah…","opts":["Olizospermia","Oligozoospermia","Astenozoospermia","Teratozoospermia","Nekrozoospermia"],"ans":1,"why":"WHO 2010: jumlah ≥ 39 juta per ejakulat (≥ 15 juta/mL); motilitas progresif ≥ 32% atau total ≥ 40%; morfologi ≥ 4%; volume ≥ 1,5 mL. Jumlah 14 juta per ejakulat jauh di bawah normal, sehingga oligozoospermia (kunci dosen). Catatan: dosen juga menulis bahwa infertilitas didefinisikan setelah 1 tahun berhubungan tanpa kontrasepsi.","ref":[44,45],"tags":["Infertilitas","Analisis sperma"],"skdi":"2","src":"coretan","cards":[{"q":"Oligozoospermia?","a":"Jumlah sperma ↓ (< 39 juta/ejakulat)"},{"q":"Astenozoospermia?","a":"Motilitas sperma ↓"},{"q":"Teratozoospermia?","a":"Morfologi normal < 4%"},{"q":"Definisi infertilitas?","a":"Tidak hamil setelah 1 tahun tanpa kontrasepsi"}]},
{"id":"og2-26","p":46,"stem":"Wanita 26 tahun P1A1 kesulitan menyusui anak pertama. Puting tampak masuk ke dalam, dapat keluar bila ditekan, tetapi segera kembali masuk bila tekanan dilepaskan. Derajat keluhannya adalah…","opts":["I","II","III","IV","V"],"ans":1,"why":"Puting terbenam (inverted nipple): derajat I mudah ditarik keluar dan bertahan; derajat II bisa ditarik keluar tetapi segera masuk lagi; derajat III tidak bisa ditarik keluar sama sekali.","ref":[41,42,43],"tags":["Laktasi"],"skdi":"4A","src":"coretan","cards":[{"q":"Inverted nipple derajat II?","a":"Bisa ditarik keluar, tapi segera masuk lagi"},{"q":"Inverted nipple derajat III?","a":"Tidak bisa ditarik keluar"}]},
{"id":"og2-27","p":46,"stem":"Wanita 20 tahun P1A0, 10 hari pascapersalinan, nyeri dan luka di payudara kiri, tanpa demam. Payudara eritema, abrasi (+), ulserasi dangkal (+), fisura dangkal (+), fluktuasi (–). Derajat keluhannya adalah…","opts":["I","II","III","IV","V"],"ans":2,"why":"Kunci dosen: cracked nipple (trauma puting) derajat III, yaitu ada abrasi, ulserasi dangkal, dan fisura dangkal. Tidak ada fluktuasi, jadi bukan abses.","ref":[41,42,43],"tags":["Laktasi"],"skdi":"4A","src":"coretan","cards":[]},
{"id":"og2-28","p":46,"stem":"Wanita 21 tahun P1A0, 2 hari postpartum, bayinya tampak kuning; ibu kesulitan menyusui anak pertamanya. Puting tampak masuk ke dalam dan tidak keluar saat dilakukan penekanan. Derajat keluhannya adalah…","opts":["I","II","III","IV","V"],"ans":2,"why":"Puting yang sama sekali tidak dapat dikeluarkan dengan penekanan adalah inverted nipple derajat III. Akibatnya bayi kurang ASI (breastfeeding jaundice).","ref":[41,42,43],"tags":["Laktasi"],"skdi":"4A","src":"coretan","cards":[]},
{"id":"og2-29","p":53,"stem":"Perempuan 22 tahun dan suami bertanya tentang kontrasepsi; belum ingin punya anak sekarang tetapi masih ingin di masa depan (menunda). Pilihan kontrasepsi yang paling baik adalah…","opts":["Pil kombinasi","AKDR","Tubektomi","Senggama terputus","Implan"],"ans":0,"why":"Kunci dosen: fase MENUNDA kehamilan (usia muda, belum punya anak), dengan urutan prioritas Pil → AKDR → Kondom → Implan → Suntik (mnemonik dosen 'PAKIS'). Pil kombinasi reversibel cepat.","ref":[47,48],"tags":["Kontrasepsi"],"skdi":"4A","src":"coretan","cards":[{"q":"Kontrasepsi fase menunda (belum punya anak)?","a":"Pil kombinasi (prioritas pertama)"},{"q":"Kontrasepsi fase mengakhiri (tidak ingin anak lagi)?","a":"Kontap (tubektomi/vasektomi)"}]},
{"id":"og2-30","p":53,"stem":"Perempuan G3P2A0 43 tahun bersama suami; tiba-tiba mengatakan tidak ingin punya anak lagi setelah ini. Pilihan kontrasepsi yang paling baik adalah…","opts":["Pil kombinasi","AKDR","Tubektomi","Senggama terputus","Implan"],"ans":2,"why":"Fase MENGAKHIRI kesuburan (usia > 35 tahun, anak cukup, tidak ingin anak lagi): kontrasepsi mantap (tubektomi/MOW).","ref":[47,48,51],"tags":["Kontrasepsi"],"skdi":"4A","src":"coretan","cards":[]},
{"id":"og2-31","p":53,"stem":"Perempuan 21 tahun dan suami panik; semalam berhubungan tanpa kontrasepsi saat masa subur dan tidak ingin hamil. Pilihan kontrasepsi yang paling baik adalah…","opts":["Pil kombinasi dosis tinggi","AKDR","Implan","Pil progestin","Suntik kombinasi"],"ans":3,"why":"Kontrasepsi darurat ≤ 72–120 jam. Kunci dosen: pil progestin (levonorgestrel 1,5 mg dosis tunggal), lebih efektif dan lebih sedikit efek samping dibanding metode Yuzpe (pil kombinasi dosis tinggi). AKDR Cu ≤ 5 hari juga sangat efektif.","ref":[52],"tags":["Kontrasepsi darurat"],"skdi":"4A","src":"coretan","cards":[{"q":"Kontrasepsi darurat oral pilihan?","a":"Levonorgestrel 1,5 mg dosis tunggal"},{"q":"Batas waktu pil kontrasepsi darurat?","a":"≤ 72 (–120) jam"}]},
{"id":"og2-32","p":53,"stem":"Perempuan P2A0 33 tahun kontrol 1 minggu setelah melahirkan; ibu dan bayi sehat, menyusui. Ingin kontrasepsi alami tanpa obat. Pilihan kontrasepsi metode alami yang dapat dilakukan adalah…","opts":["AKDR","Senggama terputus","Metode amenore laktasi","Implan","Tubektomi"],"ans":2,"why":"Metode amenore laktasi (MAL) efektif bila: bayi < 6 bulan, ASI eksklusif sesuai kebutuhan (siang dan malam), dan ibu belum haid kembali.","ref":[49],"tags":["Kontrasepsi","MAL"],"skdi":"4A","src":"coretan","cards":[{"q":"3 syarat MAL?","a":"Bayi < 6 bln, ASI eksklusif, belum haid"}]},
{"id":"og2-x01","lat":"pj-obg","ln":6,"lp":3,"stem":"Seorang wanita usia 30 tahun G1P0A0 usia kehamilan 36 minggu datang ke IGD RS dengan keluhan keluar cairan dari jalan lahir sejak 5 jam SMRS. Cairan keluar dikit demi sedikit bertambah banyak jika pasien batuk atau mengejan, berwarna jernih, dan berbau khas. Keluhan demam disangkal. Pasien juga memiliki keluhan keputihan dalam 2 minggu terakhir. Pada pemeriksaan fisik didapatkan TTV TD 120/80, N 97, RR 20, T 36,9. TFU sesuai usia kehamilan, DJJ 138 x/menit. Inspekulo tampak cairan jernih keluar dari OUE. Apakah pemeriksaan penunjang yang dapat dilakukan?","opts":["Pemeriksaan pH vagina","Kultur","Tes lakmus","USG","Urinalisis"],"ans":2,"why":"Keluar cairan jernih dari OUE pada UK 36 minggu → curiga KPD. Pemeriksaan penunjang sederhana: tes lakmus/nitrazin (kertas merah → biru karena cairan amnion basa), tes fern (arborisasi).","ref":[12],"tags":["Ketuban pecah dini"],"skdi":"3A","src":"kunci","cards":[{"q":"Tes lakmus KPD?","a":"Kertas merah → biru (amnion basa)"},{"q":"Tes fern KPD?","a":"Arborisasi (pakis) cairan amnion"}]},
{"id":"og2-x02","lat":"pj-obg","ln":13,"lp":4,"stem":"Seorang perempuan berusia 32 tahun datang ke dokter dengan keluhan nyeri pada perut sisi kanan bawahnya sejak 2 hari yang lalu. Pasien juga mengeluhkan adanya keputihan berwarna kekuningan sebelumnya. Pemeriksaan tanda vital TD 132/74, HR 98, RR 20, suhu 39 °C. Pemeriksaan fisik didapatkan adanya massa pada adneksa dengan diameter 7 cm, disertai dengan nyeri tekan. Apakah diagnosis yang paling mungkin pada kasus diatas?","opts":["Penyakit radang panggul","Abses tuboovarium","Kehamilan ektopik terganggu","Torsio ovarium","Appendisitis akut"],"ans":1,"why":"Riwayat keputihan (PID) + demam tinggi + massa adneksa nyeri 7 cm → abses tuboovarium (komplikasi PID). Terapi: antibiotik IV ± drainase.","ref":[29,30],"tags":["Abses tuboovarium","PID"],"skdi":"3A","src":"kunci","cards":[{"q":"PID + massa adneksa nyeri?","a":"Abses tuboovarium"}]},
{"id":"og2-x03","lat":"pj-obg","ln":14,"lp":4,"stem":"Seorang wanita usia 45 tahun P4A0 datang kepoliklinik dengan keluhan keluar darah dari jalan lahir. Perdarahan keluar setelah berhubungan. Keluhan lain yang dirasakan adanya perdarahan diantara masa haid sejak 8 bulan lalu. Riwayat menarke usia 11 tahun. Menikah saat usia 19 tahun. Pemeriksaan tanda vital dalam batas normal. pemeriksaan inspekulo ditemukan massa berdungkul-dungkul, mudah berdarah di portio serviks. Massa telah berinfiltrasi pada mukosa rectum. Apakah diagnosis yang tepat?","opts":["Kanker serviks stadium I","Kanker serviks stadium II","Kanker serviks stadium III","Kanker serviks stadium IV","Kanker serviks stadium V"],"ans":3,"why":"Perdarahan pascasanggama, massa serviks rapuh berdungkul. Infiltrasi ke MUKOSA rektum/kandung kemih = FIGO stadium IVA. IVB: metastasis jauh.","ref":[27,28],"tags":["Kanker serviks"],"skdi":"2","src":"kunci","cards":[{"q":"Ca serviks invasi mukosa rektum/buli?","a":"Stadium IVA"},{"q":"Ca serviks stadium IIIB?","a":"Sampai dinding panggul / hidronefrosis"},{"q":"Gejala khas Ca serviks?","a":"Perdarahan pascasanggama"}]},
{"id":"og2-x04","lat":"pj-obg","ln":16,"lp":5,"stem":"Seorang wanita 27 tahun G2P1A0 usia kehamilan 15 minggu datang dengan keluhan mual dan muntah hebat sejak 1 minggu terakhir. Pasien muntah >5x sehari, tidak nafsu makan, mengalami penurunan BB sebanyak hampir 2 kg. Pada pemeriksaan fisik didapatkan KU lemah, TTV TD 5 90/60, HR 114, RR 20, T 36,5, CRT>2 detik. Hasil urinalisa didapatkan keton +2. Apakah diagnosis yang tepat?","opts":["Emesis gravidarum","Hiperemesis gravidarum derajat I","Hiperemesis gravidarumderajat II","Hiperemesis gravidarum derajat III","Hiperemesis gravidarum derajat IV"],"ans":2,"why":"Muntah hebat dengan dehidrasi (takikardia, hipotensi, CRT > 2 s), BB turun, ketonuria → hiperemesis gravidarum derajat II. Derajat I: lemah, dehidrasi ringan; derajat III: gangguan kesadaran, ikterus (ensefalopati Wernicke).","ref":[7],"tags":["Hiperemesis gravidarum"],"skdi":"3B","src":"kunci","cards":[{"q":"Hiperemesis derajat III?","a":"Gangguan kesadaran, ikterus (Wernicke)"},{"q":"Hiperemesis derajat II?","a":"Dehidrasi nyata, ketonuria, apatis"}]},
{"id":"og2-x05","lat":"pj-obg","ln":17,"lp":5,"stem":"Wanita 35 tahun G3P2A0 hamil 38 minggu dibawa ke IGD karena kejang. Sebelumnya pasien mengeluhkan sakit kepala hebat dan pusing. Pada pemeriksaan fisik TD 190/110, HR 98, RR 20, suhu 36,7 °C. Pasien mengaku tidak pernah memiliki riwayat tekanan darah tinggi sebelumnya. Saat dilakukan pemeriksaan protein urin didapatkan hasil +3. Apakah tatalaksana definitif pada kasus diatas?","opts":["Terminasi kehamilan","MgSO4","Metildopa","Nifedipine","Nikardipin"],"ans":0,"why":"Eklampsia (kejang + hipertensi + proteinuria) pada kehamilan aterm. MgSO₄ untuk mencegah/mengatasi kejang dan antihipertensi untuk TD berat, tetapi terapi DEFINITIF adalah terminasi kehamilan setelah stabil.","ref":[5],"tags":["Eklampsia"],"skdi":"3B","src":"kunci","cards":[{"q":"Terapi definitif preeklampsia/eklampsia?","a":"Terminasi kehamilan"},{"q":"Antikonvulsan eklampsia?","a":"MgSO₄"}]},
{"id":"og2-x06","lat":"pj-obg","ln":18,"lp":5,"stem":"Seorang wanita 31 tahun datang ke poli kandungan dengan keluhan sering mengalami perdarahan pervaginam sejak pubertas. Perdarahan tersebut dikeluhkan di luar siklus mens. Pasien juga sudah 3 kali mengalami abortus dalam 5 tahun terakhir. Pada pemeriksaan tanda vital dalam batas normal. Pada pemeriksaan fisik tidak ditemukan kelainan apapun. Dokter melakukan USG dan ditemukan dua cornu uterus dengan indentasi fundus hingga os interna. Apakah diagnosis kasus diatas?","opts":["Uterus septate","Uterus subseptata","Uterus bicornu","Uterus didelfi","Uterus unicornu"],"ans":2,"why":"USG: dua kornu uterus dengan indentasi fundus yang dalam (sampai os interna) → uterus bikornu (fusi duktus Müller tidak sempurna). Uterus septum: kontur fundus luar normal dengan septum di dalam.","ref":[37],"tags":["Kelainan uterus"],"skdi":"2","src":"kunci","cards":[{"q":"Uterus bikornu vs septum?","a":"Bikornu: indentasi fundus luar; septum: fundus luar normal"}]},
{"id":"og2-x07","lat":"pj-obg","ln":20,"lp":6,"stem":"Seorang wanita usia 27 tahun P1A0 datang ke Poli Kandungan untuk konsultasi. Saat ini pasien menggunakan kontrasepsi pil KB akan tetapi lupa minum pil KB hari 10 dan 11. Pasien masih aktif berhubungan suami istri. Tindakan tepat yang harus dilakukan pasien adalah?","opts":["Minum 1 pil extra","Minum 3 pil sekaligus sekarang + kontrasepsi Cadangan","Minum 2 pil per hari selama 2hari + kontrasepsi Cadangan","Habiskan pil aktif (plasebo dibuang) + kontrasepsi Cadangan","Mulai pil strip kemasan baru + kontrasepsi cadangan"],"ans":2,"why":"Lupa 2 pil aktif berturut-turut (minggu ke-2) → minum 2 pil per hari selama 2 hari, lanjutkan sisa pil, dan pakai kontrasepsi cadangan (kondom) selama 7 hari.","ref":[50],"tags":["Kontrasepsi","Pil KB"],"skdi":"4A","src":"kunci","cards":[{"q":"Lupa 1 pil KB?","a":"Minum segera saat ingat, lanjutkan seperti biasa"},{"q":"Lupa 2 pil KB (minggu 1–2)?","a":"2 pil/hari selama 2 hari + kontrasepsi cadangan 7 hari"}]},
{"id":"og2-x08","lat":"pj-obg","ln":21,"lp":6,"stem":"Seorang wanita 57 tahun datang ke poliklinik dengan keluhan adanya benjolan diperut bawah sebelah kiri. Benjolan dirasakan semakin membesar. Keluhan disertai dengan nyeri perut. Pemeriksaan tanda vital dalam batas normal. pemeriksaan abdomen didapatkan massa pada kuadran kiri bawah abdomen, nyeri tekan, terfiksir. Dokter mencurigai suatu keganasan. Kemudian dilakukan Tindakan operatif dan didapatkan massa kistik ukuran 10x10x6 cm, tampak ada bagian seperti rambut dan gigi. Apakah komplikasi kasus diatas?","opts":["Kista dermoid","Mioma","Torsio kista","PCOS","Sheehan syndrome"],"ans":2,"why":"Massa kistik berisi rambut dan gigi = kista dermoid (teratoma matur). Komplikasi tersering: TORSIO kista (nyeri akut), juga ruptur dan degenerasi ganas (jarang).","ref":[24],"tags":["Kista dermoid"],"skdi":"2","src":"kunci","cards":[{"q":"Komplikasi tersering kista dermoid?","a":"Torsio"}]},
{"id":"og2-x09","lat":"pj-obg","ln":22,"lp":6,"stem":"Seorang wanita usia 37 tahun datang ke puskesmas untuk melakukan pap smear. Saat pemeriksaan speculum, dokter menemukan kista kecil diameter kurang lebih 1 cm, multiple dipermukaan serviks. Tidak ada tanda infeksi, discharge (-), perdarahan (-) Apakah diagnosis dan penyebab kasus diatas?","opts":["Kistanabothi,restrukturasiendoserviks","Kista gartner, obstruksi kanalis wolfii","Kista bartolini, obstruksi kelenjar bartolini","Ca serviks, infeksi HPV 16,18","Polip serviks, hyperplasia epitel serviiks"],"ans":0,"why":"Kista kecil multipel di permukaan serviks tanpa tanda infeksi → kista Naboth: kelenjar endoserviks tersumbat oleh epitel skuamosa saat metaplasia (restrukturisasi endoserviks). Tidak perlu terapi.","ref":[28],"tags":["Kista Naboti"],"skdi":"4A","src":"kunci","cards":[{"q":"Kista Naboth?","a":"Sumbatan kelenjar endoserviks oleh metaplasia skuamosa"},{"q":"Kista Gartner?","a":"Sisa duktus Wolffi (Mesonefros) di dinding vagina"}]},
{"id":"og2-x10","lat":"pj-obg","ln":24,"lp":7,"stem":"Seorang wanita usia 32 tahun datang kepoliklinik diantar suaminya ingin berkonsultasi mengenai kehamilannua. Pasien hamil ketiga dengan riwayat keguguran pada kehamilan sebelumnya. Pemeriksaan laboratorium didapatkan IgM toksoplasma (-), IgG toxoplasma (+). Apakah diagnosis yang paling mungkin?","opts":["Tidak ada infeksi","False positif","Infeksi akut","Infeksi latent","Infeksi kronik"],"ans":3,"why":"IgG toksoplasma (+) dan IgM (−) → infeksi lampau/laten (imun), risiko transmisi rendah. IgM (+) → infeksi baru/akut (konfirmasi dengan avidity IgG).","ref":[16],"tags":["Toksoplasmosis"],"skdi":"3A","src":"kunci","cards":[{"q":"Toksoplasma IgG +, IgM −?","a":"Infeksi lampau/laten"},{"q":"Toksoplasma IgM +: konfirmasi?","a":"Uji aviditas IgG"}]},
{"id":"og2-x11","lat":"pj-obg","ln":25,"lp":7,"stem":"Seorang wanita 37 tahun mengeluh sesak napas. Tanda vital TD 140/78, HR 107, RR 24. Pada pemeriksaan laboratorium SGOT/SPT dalam batas normal, parameter yang lain juga dalam batas normal. Pada foto thorax 7 ditemukan adanya cairan pada basal paru. USG abdomen ditemukan adanya massa pada ovarium dextra disertai ascites (+). Apakah diagnosis pada pasien diatas","opts":["Sindrom hepatorenal","Sindroma nefrotik","Eisenmenger syndrome","Meig syndrome","Kartegener syndrome"],"ans":3,"why":"Trias Meigs: tumor ovarium jinak (fibroma), asites, efusi pleura (sering kanan), yang hilang setelah tumor diangkat.","ref":[24],"tags":["Sindrom Meigs"],"skdi":"2","src":"kunci","cards":[{"q":"Trias sindrom Meigs?","a":"Tumor ovarium (fibroma), asites, efusi pleura"}]},
{"id":"og2-x12","lat":"aipki-obg","ln":3,"lp":2,"stem":"Wanita 27 tahun G1P0A0 uk 35 minggu datang ke IGD mengatakan keluar cairan bening dari jalan lahir sejak 2 jam yang lalu. Cairan bening tidak bercampur darah. Pemeriksaan TTV dalam batas normal. Pemeriksaan VT tidak didapatkan pembukaan, vaginal pooling (+). Pemeriksaan cairan mikroskopik tamb=pak gambaran daun pakis Apakah diagnosis kasus diatas?","opts":["Ketuban pecah dini preterm","Ketuban pecah dini sangat preterem","Koriamnionitis","Ketuban pecah dini","Partus prematurus imminen"],"ans":0,"why":"Cairan bening, pooling (+), fern test (+) pada UK 35 minggu tanpa pembukaan → KPD PRETERM (sebelum 37 minggu). Sangat preterm: < 34 minggu (atau < 28–32 minggu, tergantung pedoman).","ref":[12],"tags":["Ketuban pecah dini"],"skdi":"3A","src":"kunci","cards":[{"q":"KPD preterm?","a":"Ketuban pecah sebelum inpartu pada UK < 37 minggu"}]},
{"id":"og2-x13","lat":"aipki-obg","ln":10,"lp":4,"stem":"Seorang wanita usia 27 tahun G2P0A1 usia kehamilan 30 minggu datang ke poliklinik kandungan dengan keluhan kandungannya dirasa lambat berkembang. Pada pemeriksaan fisik didapatkan TTV TD 120/80, HR 95, RR 20, T afebris. Pemeriksaan obstetri didapatkan TFU 20 cm, DJJ 140x/menit. Bagian janin sangat mudah teraba. Pemeriksaan USG didapatkan AFI 4 cm. Apakah komplikasi yang mungkin terjadi pada kasus?","opts":["Potter syndrome","Sindrom post maturitas","Down syndrome","Edward syndrome","Turner syndrome"],"ans":0,"why":"TFU lebih kecil dari usia kehamilan, bagian janin mudah teraba, AFI < 5 cm → oligohidramnion. Komplikasi: Potter sequence (hipoplasia paru, wajah Potter, deformitas tungkai), kompresi tali pusat.","ref":[19,21],"tags":["Oligohidramnion"],"skdi":"3A","src":"kunci","cards":[{"q":"Oligohidramnion: AFI?","a":"< 5 cm"},{"q":"Polihidramnion: AFI?","a":"> 24–25 cm"}]},
{"id":"og2-x14","lat":"aipki-obg","ln":16,"lp":5,"stem":"Seorang dokter menemukan massa kistik tunggal dengan diameter 2 cm pada seorang pasien wanita usia 37 tahun pada ovariumnya. Kemudian dokter melakukan kistektomi. Secara makroskopik massa tersebut terdiri dari beberapa kista yang dibatasi dinding tipis dan secara mikroskopis tampak dinding kista dibatasi oleh sel Theca dan sel Granulosit. Massa apakah sel tersebut?","opts":["Kista coklat","Kista lutein","Kista folikel","Teratoma","Cystadenoma"],"ans":2,"why":"Kista ovarium kecil berdinding tipis dilapisi sel granulosa dan teka → kista folikel (kista fungsional, sering regresi spontan). Kista lutein: sel luteinisasi (terkait hCG tinggi/mola); kista coklat: endometriosis.","ref":[24],"tags":["Kista ovarium fungsional"],"skdi":"3A","src":"kunci","cards":[{"q":"Kista folikel: lapisan sel?","a":"Granulosa + teka"},{"q":"Kista teka lutein terkait…?","a":"hCG tinggi (mola, gemelli)"}]},
{"id":"og2-x15","lat":"aipki-obg","ln":17,"lp":5,"stem":"Seorang wanita berusia 26 tahun sudah menikah selama 5 tahun namun belum hamil memeriksakan diri ke dokter kandungan diantar suaminya. Menurut keterangan suami pasien suka memelihara kucing liar di rumah. Dari Hasil pemeriksaan penunjang IgG dan IgM Toxoplasma (+) Bagaimanakah cara penularan penyakit tersebut?","opts":["Airbone","Fecal oral","Cairan tubuh","Droplet","Menembus kulit"],"ans":1,"why":"Toxoplasma gondii ditularkan secara FEKAL-ORAL: menelan ookista dari tinja kucing (tanah, sayur tidak dicuci) atau kista jaringan dari daging setengah matang; juga transplasenta.","ref":[16],"tags":["Toksoplasmosis"],"skdi":"3A","src":"kunci","cards":[{"q":"Hospes definitif Toxoplasma?","a":"Kucing"}]},
{"id":"og2-x16","lat":"aipki-obg","ln":18,"lp":5,"stem":"Seorang wanita 23 tahun G1P0A0 hamil 36 minggu dibawa ke IGD RS dengan keluhan nyeri kepala dan sesak nafas sejak 12 jam yang lalu. Pasien mengatakan tekanan darahnya meningkat semenjak trimester IlI. Pasien menyangkal adanya hipertensi sebelum kehamilan. Pada didapatkan TD 180/100, HR 110, RR 30, T 37C. Pada pemeriksaan fisik didapatkan suara ronkhi (+) pada kedua lapangan paru. Proteinuria +3. Apakah diagnosis dan tatalaksana yang paling tepat pada pasien?","opts":["Preeklampsia berat - MgSO4 bolus lambat","Preeklampsia berat - MgSO4 bolus cepat","Superimposed preeklampsia - MgSO4 drip","Hipertensi kronis - MgSO4 bolus lambat","Hipertensi kronis - MgSO4 bolus cepat"],"ans":0,"why":"TD ≥ 160/110 + proteinuria + edema paru (komplikasi) pada hamil 36 minggu, tanpa hipertensi sebelumnya → preeklampsia berat. MgSO₄ dosis awal 4 g IV diberikan PERLAHAN (15–20 menit) untuk mencegah depresi napas/henti jantung.","ref":[5],"tags":["Preeklampsia berat"],"skdi":"3B","src":"kunci","cards":[{"q":"MgSO₄ loading preeklampsia?","a":"4 g IV perlahan 15–20 menit"},{"q":"Tanda toksisitas MgSO₄?","a":"Refleks patela hilang, RR < 16, urin < 30 mL/jam"},{"q":"Antidot MgSO₄?","a":"Kalsium glukonat 10% 1 g IV"}]},
{"id":"og2-x17","lat":"aipki-obg","ln":19,"lp":5,"stem":"Seorang wanita usia 26 tahun, G1P0A0, UK 25 minggu datang ke dokter untuk ANC rutin. TTV dalam batas normal. Pemeriksaan fisik didapatkan TFU terletak 2 jari di bawah prosesus xiphoideus dengan letak kepala di bawah. Pemeriksaan kadar gula didapatkan TTGO 75 g, GDP 100 mg/dL, GD1PP 190 mg/dL, GD2PP 140 mg/dL. Apakah tatalaksana awal yang dapat diberikan?","opts":["Insulin","Pengaturan diet dan gaya hidup","Metformin","Glibenclamid","Glimepirid"],"ans":1,"why":"TTGO 75 g (IADPSG): DMG bila ≥ 1 nilai abnormal: puasa ≥ 92, 1 jam ≥ 180, 2 jam ≥ 153 mg/dL. GDP 100 dan 1 jam 190 → DMG. Terapi awal: diet dan modifikasi gaya hidup 1–2 minggu; insulin bila target tidak tercapai.","ref":[9],"tags":["Diabetes gestasional"],"skdi":"3A","src":"kunci","cards":[{"q":"Batas TTGO DMG: puasa / 1 jam / 2 jam?","a":"≥ 92 / ≥ 180 / ≥ 153 mg/dL"},{"q":"Terapi awal DMG?","a":"Diet + aktivitas fisik"},{"q":"Farmakoterapi pilihan DMG?","a":"Insulin"}]},
{"id":"og2-x18","lat":"aipki-obg","ln":20,"lp":6,"stem":"Seorang wanita usia 21 tahun P1A0 datang ke RS dengan keluhan massa kemerahan dan nyeri pada payudara kiri sejak 6 hari yang lalu. Pemeriksaan fisik TD 120/70, HR 86 , RR 20, T 38,1. Payudara kiri tampak edema, eritem, dan fluktuatif (+) Apakah diagnose dan edukasi yang dapat diberikan?","opts":["Mastitis, lanjutkan menyusui dengan kedua payudara","Abses mamae, tidak menyusui secara langsung terlebih dahulu","Mastalgia, lanjutkan menyusui di kedua payudara","Abses mammae, oleskan ASI pada payudara yang sakit","Mastitis, perbaiki posisi menyusui"],"ans":1,"why":"Massa payudara eritem, nyeri, FLUKTUATIF + demam → abses payudara. Tatalaksana: insisi drainase/aspirasi + antibiotik; menyusui langsung dari payudara yang sakit dihentikan sementara (ASI dipompa/dibuang), tetap menyusui dari sisi sehat.","ref":[41,42],"tags":["Abses payudara"],"skdi":"3A","src":"kunci","cards":[{"q":"Mastitis vs abses payudara?","a":"Abses: ada fluktuasi"},{"q":"Mastitis: menyusui?","a":"Tetap lanjutkan dari kedua payudara"}]},
{"id":"og2-x19","lat":"aipki-obg","ln":21,"lp":6,"stem":"Seorang wanita usia 28 tahun datang ke dokter karena keluhan puting kiri yang tidak bisa keluar. Ia mengaku kesulitan menyusui. Namun, puting dapat keluar bila ditekan. Bila tekanan tersebut dilepas, puting segera kembali masuk kembali. Apakah diagnosis kasus diatas?","opts":["Inverted nipple grade I","Inverted nipple grade II","Inverted nipple grade III","Inverted nipple grade IV","Inverted nipple grade V"],"ans":1,"why":"Grade I: puting mudah dikeluarkan dan bertahan keluar. Grade II: bisa dikeluarkan dengan tekanan tetapi segera masuk kembali saat dilepas. Grade III: tidak bisa dikeluarkan sama sekali.","ref":[41],"tags":["Inverted nipple"],"skdi":"3A","src":"kunci","cards":[{"q":"Inverted nipple grade II?","a":"Bisa dikeluarkan tapi segera masuk lagi"},{"q":"Inverted nipple grade III?","a":"Tidak bisa dikeluarkan"}]},
{"id":"og2-x20","lat":"aipki-obg","ln":22,"lp":6,"stem":"Seorang perempuan usia 64 tahun datang ke puskesmas dengan keluhan keluar benjolan dari jalan lahir. Pasien memiliki 6 orang anak, Riwayat SC sebelumnya disangkal. Pada pemeriksaan fisik didapatkan tekanan darah 130/70, denyut nadi 89, frekuensi napas 20 dan suhu 36,5. Didapatkan benjolan tereversi total keluar introitus vagina Apakah diagnosis dan tatalaksana yang sesuai untuk kasus diatas?","opts":["Prolaps uteri grade I, histerektomi","Prolaps uteri grade IV, pasang cincing pessarium","Prolaps uteri grade III, histerektomi","Prolaps uteri grade IV, histerektomi","Prolaps uteri grade II, vaginoraphy"],"ans":3,"why":"Uterus keluar seluruhnya dari introitus (total, prosidensia) → prolaps uteri grade IV. Pada pasien pascamenopause yang sudah tidak ingin anak: histerektomi vaginal. Pesarium untuk yang tidak bisa/menolak operasi.","ref":[25],"tags":["Prolaps uteri"],"skdi":"3A","src":"kunci","cards":[{"q":"Prolaps uteri grade IV?","a":"Seluruh uterus keluar introitus (prosidensia)"}]},
{"id":"og2-x21","lat":"aipki-obg","ln":23,"lp":6,"stem":"Seorang perempuan usia 35 tahun, datang ke klinik dengan keluhan nyeri perut bawah sejak 5 hari yang lalu, disertai demam yang hilang timbul, Nyeri saat bersenggama (+), keputihan (+), telat menstruasi (-). Pada pemeriksaan fisik TD 130/80, HR 90, RR 20, Suhu 38.3. Pemeriksaan abdomen didapatkan nyeri tekan terutama kiri bawah, tidak terdapat nyeri tekan lepas dan massa (-). Pada pemeriksaan VT ditemukan nyeri goyang portio, nyeri tekan adnexa kiri dan terbasa massa berfluktuasi pada adnexa kiri. Pada pemeriksaan bakteriologis didapatkan basil, warna merah. Apakah etiologi kasus diatas?","opts":["E. coli","E. hystolitica","N. gonorrhea","S. aureus","Pseudomonas aeruginosa"],"ans":0,"why":"PID dengan massa adneksa berfluktuasi (abses tuboovarium); bakteriologis basil Gram NEGATIF (merah) → E. coli (flora polimikroba, bersama anaerob). N. gonorrhoeae adalah diplokokus (bukan basil).","ref":[29,30],"tags":["Abses tuboovarium","PID"],"skdi":"3A","src":"kunci","cards":[]},
{"id":"og2-x22","lat":"aipki-obg","ln":24,"lp":6,"stem":"Seorang perempuan, usia 33 tahun. Sudah memiliki anak 1. Keluhan utama daerah genital bau pesing dan keluar cairan. Riwayat melahirkan dengan vakum karena bayi besar beberapa bulan yang lalu. Dari pemeriksaan tanda vital tekanan darah 120/80, nadi 88, laju napas 16, suhu 36,5. Pada pemeriksaan inspekulo didapatkan cairan jernih dan pesing pada fornix posterior. Apakah diagnosis kasus diatas?","opts":["Fistula vesico vaginal","Sistokel","Rektokel","Enterokel","Prosidensia uteri"],"ans":0,"why":"Keluar cairan urin (berbau pesing) terus-menerus dari vagina setelah persalinan sulit/tindakan (vakum, partus lama → nekrosis tekanan) → fistula vesikovaginal.","ref":[26],"tags":["Fistula vesikovaginal"],"skdi":"2","src":"kunci","cards":[{"q":"Penyebab tersering fistula vesikovaginal di negara berkembang?","a":"Partus lama/macet (nekrosis tekanan)"}]},
{"id":"og2-x23","lat":"aipki-obg","ln":25,"lp":7,"stem":"Seorang perempuan usia 28 tahun sudah menikah, datang ke puskesmas untuk mengikuti kegiatan IVA test. Saat ini tidak ada keluhan. Pada pemeriksaan tanda vital dalam batas normal, saat dilakukan pemeriksaan inpekulo didapatkan portio tebal dan kenyal, namun tampak massa multiple berukuran 3 – 5 mm berisi cairan, berwarna agak pucat disertai eritema disekitarnya. Adnexa kanan dan kiri dalam batas normal. Apakah etiologi kasus diatas?","opts":["Obstruksi kelenjar bartolini","Infeksi kelenjar bartolini","Obstruksi ductus mesonefros","Restrukturasi endoserviks","Hiperplasia epitel serviks"],"ans":3,"why":"Kista multipel kecil berisi cairan di portio → kista Naboth akibat restrukturisasi (metaplasia skuamosa) endoserviks yang menutup kelenjar.","ref":[28],"tags":["Kista Naboti"],"skdi":"4A","src":"kunci","cards":[]},
{"id":"og2-x24","lat":"aipki-obg","ln":26,"lp":7,"stem":"Wanita 35 tahun, G4P3A0 usia kehamilan 35 minggu datang ke IGD RS dengan tidak merasakan gerak janin sejak 3 hari, tidak ada riwayat trauma, tidak ada air ketuban yang keluar dari jalan lahir. Riwayat DM (+) pada orang tua, IMT 23, TD 130/70, HR 92, RR 20 dan suhu 37.6. Pemeriksaan TFU setinggi pertengahan umbilical-prosesus-xipoideus, pemeriksaan leopold didapatkan janin satu, letak kepala blm masuk PAP, punggung kanan, DJJ (-). Apakah temuan yang tidak terdapat pada pemeriksaan penunjang?","opts":["Spalding sign","Ball sign","Helix sign","Robert sign","Whirpool sign"],"ans":4,"why":"Gerak janin tidak dirasa + DJJ (−) → IUFD. Tanda radiologis IUFD: Spalding (tumpang tindih tulang kepala), Robert (gas dalam pembuluh janin), ball sign (kepala/tulang belakang hiperfleksi), halo sign. Whirlpool sign = torsio (ovarium/testis/volvulus), bukan IUFD.","ref":[15],"tags":["IUFD"],"skdi":"3A","src":"kunci","cards":[{"q":"Spalding sign?","a":"Tulang tengkorak janin tumpang tindih (IUFD)"},{"q":"Robert sign?","a":"Gas dalam pembuluh darah janin (IUFD)"},{"q":"Whirlpool sign?","a":"Torsio (pedikel terpuntir)"}]},
{"id":"og2-x25","lat":"aipki-obg","ln":27,"lp":7,"stem":"Seorang perempuan usia 29 tahun datang ke poliklinik ingin berkonsultasi karena belum memiliki keturunan setelah menikah selama 3 tahun. Pasien dan suami berhubungan seksual aktif tanpa pengaman. Apakah diagnosis pada pasien diatas?","opts":["Infertilitas primer","Infertilitas sekunder","Amenore primer","Amenore sekunder","Oligomenorhea"],"ans":0,"why":"Tidak hamil setelah ≥ 12 bulan hubungan seksual teratur tanpa kontrasepsi dan BELUM pernah hamil → infertilitas primer. Sekunder: pernah hamil sebelumnya.","ref":[44,45],"tags":["Infertilitas"],"skdi":"3A","src":"kunci","cards":[{"q":"Definisi infertilitas?","a":"Tidak hamil ≥ 12 bulan hubungan teratur tanpa kontrasepsi"},{"q":"Infertilitas sekunder?","a":"Pernah hamil sebelumnya"}]},
{"id":"og2-x26","lat":"aipki-obg","ln":28,"lp":7,"stem":"Seorang perempuan usia 33 tahun datang ke poliklinik untuk konsultasi. Pasien menggunakan minipil sejak 2 bulan lalu. Pasien mengeluhkan bercak perdarahan dari jalan lahir sejak 1 minggu yang lalu. Tanda-tanda vital dalam batas normal. Apakah tindakan yang sebaiknya diberikan?","opts":["Mengganti pil KB dengan pil KB kombinasi","Memberikan pil estrogen","Meningkatkan dosis progesterone pada pil KB","Menyarankan pasien untuk mengganti metode KB","Meneruskan pemberian pil Kb disertai dengan observasi"],"ans":4,"why":"Bercak/spotting adalah efek samping tersering kontrasepsi progestin (minipil), terutama bulan-bulan awal, dan tidak berbahaya → konseling, lanjutkan pil, observasi.","ref":[50],"tags":["Kontrasepsi","Minipil"],"skdi":"4A","src":"kunci","cards":[{"q":"Efek samping tersering minipil/progestin?","a":"Perdarahan bercak (spotting)"}]},
{"id":"og2-x27","lat":"aipki-obg","ln":29,"lp":7,"stem":"Seorang wanita usia 45 tahun P2A0 datang ke poliklinik dengan keluhan nyeri perut bawah hebat saat haid dan haid dengan jumlah banyak sejak 3 bulan terakhir. Penurunan berat badan disangkal. Pemeriksaan TTV dalam batas normal. Pemeriksaan fisik ditemukan uterus membesar difus. Plano test (−). Apakah kemungkinan diagnosis kasus di atas?","opts":["Leiomioma","Adenomiosis","Endometriosis","Kista ovarium","Kista coklat"],"ans":1,"why":"Dismenore berat + menoragia pada multipara usia 40-an dengan uterus membesar DIFUS (globular, simetris) → adenomiosis (jaringan endometrium di dalam miometrium). Mioma: uterus membesar berbenjol/asimetris.","ref":[32,33],"tags":["Adenomiosis","AUB"],"skdi":"3A","src":"kunci","cards":[{"q":"Adenomiosis: uterus?","a":"Membesar difus (globular)"},{"q":"Mioma: uterus?","a":"Membesar berbenjol (asimetris)"}]},
{"id":"og2-x28","lat":"aipki-obg","ln":30,"lp":8,"stem":"Seorang wanita 19 tahun G1P0A0 datang dengan keluhan mual muntah hebat yang dialami sejak beberapa hari lalu. Pasien mengaku mengalami penurunan nafsu makan. Pasien belum mendapatkan menstruasi dalam 3 bulan terakhir dan biasanya siklus menstruasi pasien tidak teratur. Pemeriksaan fisik didapatkan pasien compos mentis dan tampak lemah dengan TTV TD 100/70, HR 95, RR 20, T 37. Tes Plano (+). Apakah diagnosis dan terapi yang tepat?","opts":["Emesis gravidarum, Vitamin A","Bulimia, Vitamin B complex","Hiperemesis gravidarum grade 1, Vitamin B6","Hiperemesis gravidarum grade 2, Vitamin B12","Hiperemesis gravidarum grade 3, Asam folat"],"ans":2,"why":"Mual-muntah hebat dengan nafsu makan turun dan lemah, hemodinamik masih baik, kesadaran baik → hiperemesis gravidarum tingkat I. Terapi: vitamin B6 (piridoksin) ± doksilamin, rehidrasi, antiemetik.","ref":[7],"tags":["Hiperemesis gravidarum"],"skdi":"3B","src":"kunci","cards":[{"q":"Terapi awal mual muntah kehamilan?","a":"Vitamin B6 (piridoksin) ± doksilamin"}]},
{"id":"og2-x29","lat":"aipki-obg","ln":31,"lp":8,"stem":"Seorang wanita 21 tahun P1A0 datang kepuskesmas untuk berkonsultasi mengenai KB. Pasien ingin mengggunakan KB tanpa obat dan alat. Pasien sedang menyusui ASI ekslusif 4 minggu. Pasien belum menstruasi. Pemeriksaan TD 130/80, HR 98, T 36.7, RR 20. Pemeriskaan fisik tidak ditemukan kelainan Apakah pilihan KB yang sesuai pada kondisi diatas?","opts":["Suntik kombinasi","Tubektomi","AKDR","Implan","Metode amenorrhea laktasi"],"ans":4,"why":"Metode amenore laktasi (MAL) efektif bila: menyusui eksklusif (siang-malam), belum haid, bayi < 6 bulan. Memenuhi semua syarat dan pasien ingin KB tanpa obat/alat → MAL.","ref":[49],"tags":["Kontrasepsi","MAL"],"skdi":"4A","src":"kunci","cards":[{"q":"Syarat metode amenore laktasi (3)?","a":"ASI eksklusif, belum haid, bayi < 6 bulan"}]},
{"id":"og2-x30","lat":"aipki-obg","ln":32,"lp":8,"stem":"Seorang wanita 59 tahun datang dengan keluhan sulit menahan buang air kecil. Keluhan dirasakan terutama ketika saat mengangkat berat, mengejan dan ketika batuk. Riwayat melahirkan saat usia 32 tahun, pervaginam dengan berat 4100 gram. Pemeriksaan inspekulo didapatkan massa keluar dari dinding anterior vagina. Kemungkinan diagnosis pada pasien diatas ?","opts":["Prolaps uteri","Polip uteri","Rektokel","Sistokel","Fistula urogenital"],"ans":3,"why":"Inkontinensia urin saat mengejan/batuk (stres) + massa keluar dari dinding ANTERIOR vagina pada multipara riwayat bayi besar → sistokel (prolaps kandung kemih). Rektokel: dinding posterior.","ref":[25],"tags":["Sistokel","Inkontinensia stres"],"skdi":"3A","src":"kunci","cards":[{"q":"Sistokel: dinding vagina?","a":"Anterior"},{"q":"Rektokel: dinding vagina?","a":"Posterior"}]},
{"id":"og2-x31","lat":"fk-obgped","ln":4,"lp":19,"stem":"Perempuan 22 tahun G1P0A0 UK 21 minggu dengan lemas, mudah lelah, nafsu makan turun 2 minggu. Konjungtiva anemis, riwayat kurang darah sejak remaja. Hb 9, MCV 120, MCH 33; apusan darah tepi: neutrofil hipersegmentasi. Apakah diagnosis yang mungkin?","opts":["Anemia defisiensi besi","Anemia penyakit kronik","Anemia defisiensi folat","Anemia perdarahan","Alkoholisme"],"ans":2,"why":"Anemia MAKROSITIK (MCV 120) dengan neutrofil hipersegmentasi → anemia megaloblastik; pada kehamilan tersering defisiensi asam FOLAT (kebutuhan meningkat). ADB: mikrositik hipokrom.","ref":[8],"tags":["Anemia kehamilan"],"skdi":"4A","src":"kunci","cards":[],"xp":[20,21]},
{"id":"og2-x32","lat":"fk-obgped","ln":5,"lp":22,"stem":"Perempuan 22 tahun primigravida UK 32 minggu ke IGD dengan nyeri kepala sejak 1 minggu, tanpa riwayat penyakit kronis. TD 180/100, uterus sesuai 32 minggu, protein urin dipstik +2, saraf kranial intak, refleks patela (+). Apakah tatalaksana awal yang tepat?","opts":["MgSO₄ 40% 15 cc dalam 500 cc aquades IV 28 tpm selama 6 jam","MgSO₄ 40% 10 cc dalam 500 cc aquades IV 28 tpm selama 6 jam","Diazepam per rektal 10 mg","MgSO₄ 40% 15 cc dalam 500 cc aquades IV selama 15 menit","MgSO₄ 40% 10 cc dalam 10 cc aquades IV selama 15 menit"],"ans":4,"why":"Preeklampsia berat (TD ≥ 160/110 + proteinuria) → dosis awal (loading) MgSO₄ 4 g = 10 cc MgSO₄ 40% diencerkan dengan 10 cc aquades, IV perlahan 15 menit; lalu maintenance 6 g (15 cc 40%) dalam 500 cc RL, 28 tpm selama 6 jam. Diazepam hanya lini kedua.","ref":[5],"tags":["Preeklampsia berat","MgSO4"],"skdi":"3B","src":"kunci","cards":[{"q":"Loading MgSO₄ (regimen Indonesia)?","a":"4 g (10 cc 40%) + 10 cc aquades IV 15 menit"},{"q":"Maintenance MgSO₄ (regimen Indonesia)?","a":"6 g (15 cc 40%) dalam 500 cc RL, 28 tpm/6 jam"}],"xp":[23,24]},
{"id":"og2-x33","lat":"fk-obgped","ln":9,"lp":43,"stem":"Perempuan 35 tahun P4A0 dengan perdarahan pascasanggama dan perdarahan di luar siklus haid; menikah usia 15 tahun dan berganti-ganti pasangan. Inspekulo: bercak darah dari OUE, portio tidak rata. Apakah pemeriksaan penunjang yang paling tepat (diagnosis definitif)?","opts":["USG transvaginal","IVA test","Pap smear","Biopsi serviks","CT scan"],"ans":3,"why":"Lesi serviks yang tampak/simtomatik (perdarahan pascasanggama, portio tidak rata) → diagnosis DEFINITIF dengan biopsi serviks (histopatologi). IVA/Pap smear untuk skrining wanita tanpa lesi; CT untuk staging.","ref":[27,28],"tags":["Kanker serviks"],"skdi":"2","src":"kunci","cards":[{"q":"Diagnosis definitif kanker serviks?","a":"Biopsi serviks (histopatologi)"},{"q":"Skrining kanker serviks di puskesmas?","a":"IVA / Pap smear"}],"xp":[44,45]},
{"id":"og2-x34","lat":"fk-obgped","ln":10,"lp":47,"stem":"Perempuan 25 tahun ke IGD dengan nyeri hebat mendadak sejak 3 jam disertai mual muntah. TD 130/80, HR 102, afebris. Bimanual: massa sebesar bola pingpong di adneksa, nyeri tekan VAS 7. Hb 12, leukosit 9000, tes kehamilan negatif. Apakah tatalaksana yang paling tepat?","opts":["Dilatasi dan kuretase","Apendektomi","Laparotomi eksplorasi","Levofloksasin 1×500 mg 14 hari","Detorsi"],"ans":4,"why":"Nyeri hebat mendadak + mual muntah + massa adneksa nyeri, tes kehamilan (−), tanpa demam/leukositosis → torsio kista ovarium. Tatalaksana: operasi segera (laparoskopi) untuk DETORSI dan mempertahankan ovarium ± kistektomi.","ref":[24],"tags":["Torsio ovarium"],"skdi":"2","src":"kunci","cards":[{"q":"Torsio ovarium: tatalaksana?","a":"Laparoskopi detorsi (pertahankan ovarium)"}],"xp":[48,49]},
{"id":"og2-x35","lat":"fk-obgped","ln":11,"lp":50,"stem":"Wanita 23 tahun P1A0 postpartum hari ke-2; anaknya sulit menyusu sejak lahir. Kedua puting masuk ke dalam dan tetap masuk walau areola ditekan. Apakah diagnosis?","opts":["Inverted nipple grade 1","Inverted nipple grade 2","Inverted nipple grade 3","Inverted nipple grade 4","Inverted nipple grade 5"],"ans":2,"why":"Puting tidak dapat dikeluarkan sama sekali walaupun ditekan/ditarik → inverted nipple grade 3 (fibrosis berat).","ref":[41],"tags":["Inverted nipple"],"skdi":"3A","src":"kunci","cards":[],"xp":[51,52]},
{"id":"og2-x36","lat":"fk-obgped","ln":13,"lp":58,"stem":"Perempuan 26 tahun mudah berdarah dan nyeri saat bersenggama. Inspekulo: benjolan bertangkai ukuran 2×4 cm yang menempel di serviks. Bagaimana tatalaksananya?","opts":["Ekstirpasi","Eksisi","Insisi","Elektrokauter","Histerektomi"],"ans":0,"why":"Massa bertangkai di serviks dengan perdarahan kontak → polip serviks. Tatalaksana: ekstirpasi (dipuntir/dipotong pada tangkainya) + pemeriksaan histopatologi.","ref":[28],"tags":["Polip serviks"],"skdi":"3A","src":"kunci","cards":[{"q":"Polip serviks: tatalaksana?","a":"Ekstirpasi + histopatologi"}],"xp":[59,60]},
{"id":"og2-x37","lat":"fk-obgped","ln":14,"lp":62,"stem":"Nn. V, 21 tahun, dengan benjolan di kemaluan, tidak nyeri tetapi mengganjal. Afebris. Genitalia eksterna: benjolan pada lipatan labium bagian posterior, kistik, batas tegas, kemerahan, nyeri tekan (−). Apakah diagnosis dan tatalaksananya?","opts":["Kista Naboti, observasi","Kista Gartner, insisi drainase","Kista Bartolin, marsupialisasi","Abses Bartolin, insisi drainase dan antibiotik","Kista sebasea labia mayora, drainase"],"ans":2,"why":"Massa kistik tidak nyeri di posterior labium (arah jam 4/8, muara kelenjar Bartolin) → kista Bartolin. Bila simtomatik: marsupialisasi (atau kateter Word). Abses bila nyeri, merah, fluktuasi, demam.","ref":[26],"tags":["Kista Bartolin"],"skdi":"3A","src":"kunci","cards":[{"q":"Kista Bartolin: tatalaksana?","a":"Marsupialisasi / kateter Word"},{"q":"Lokasi kelenjar Bartolin?","a":"Posterolateral introitus (jam 4 dan 8)"}],"xp":[63,64]},
{"id":"og2-x38","lat":"fk-obgped","ln":15,"lp":66,"stem":"Wanita 26 tahun 10 hari pascapersalinan, menyusui, dengan nyeri hebat dan bengkak payudara kanan sejak 3 hari; ASI dari payudara kanan tidak keluar. Suhu 38,6 °C, payudara kanan merah, nyeri tekan (+), fluktuasi (+). Apakah diagnosis dan tatalaksana nonfarmakologi yang tepat?","opts":["Mastitis, kompres air hangat","Mastitis, kompres air dingin","Abses payudara, insisi drainase dan berhenti menyusui sementara","Bendungan ASI, kompres air hangat","Bendungan ASI, kompres air dingin"],"ans":2,"why":"Fluktuasi (+) + demam → abses payudara: insisi drainase (atau aspirasi) + antibiotik; hentikan sementara menyusui dari payudara yang sakit (ASI dipompa), tetap menyusui dari sisi sehat.","ref":[41,42],"tags":["Abses payudara"],"skdi":"3A","src":"kunci","cards":[],"xp":[67,68]}
]});
